  } catch (IllegalArgumentException | IllegalStateException | SecurityException | NullPointerException | UnsupportedOperationException | RuntimeException e) {
    // Handle the exception, e.g., log the error and rethrow or provide a meaningful message to the user
    e.printStackTrace();
    throw new RuntimeException("Failed to validate FlinkPipelineOptions: " + e.getMessage(), e);
  }
